import{_ as e}from"./pageheader-D3DwWmpK.js";import{_ as s,c as t,e as v,f as i,n as l,F as c}from"./index-BTZJWR2b.js";const o={__name:"gutters",setup(r){const d={title:"Utilities",currentpage:"Gutters",activepage:"Gutters"};return(n,a)=>(v(),t(c,null,[i(e,{propData:d}),a[0]||(a[0]=l('<div class="row" data-v-8a55e896><div class="col-xl-12" data-v-8a55e896><div class="card custom-card" data-v-8a55e896><div class="card-header" data-v-8a55e896><div class="card-title" data-v-8a55e896> Horizontal gutters </div></div><div class="card-body" data-v-8a55e896><p data-v-8a55e896><span class="text-danger" data-v-8a55e896>.gx-*</span> classes can be used to control the horizontal gutter widths. The <span class="text-danger" data-v-8a55e896>.container</span> or <span class="text-danger" data-v-8a55e896>.container-fluid</span>&gt; parent may need to be adjusted if larger gutters are used too to avoid unwanted overflow, using a matching padding utility. For example, in the following example we’ve increased the padding with <span class="text-danger" data-v-8a55e896>.px-4</span>: </p><div class="container px-4 mb-3" data-v-8a55e896><div class="row gx-5" data-v-8a55e896><div class="col" data-v-8a55e896><div class="p-3 mb-1 border bg-light" data-v-8a55e896>Custom column padding</div></div><div class="col" data-v-8a55e896><div class="p-3 mb-1 border bg-light" data-v-8a55e896>Custom column padding</div></div></div></div><p data-v-8a55e896>An alternative solution is to add a wrapper around the <span class="text-danger" data-v-8a55e896>.row</span> with the <span class="text-danger" data-v-8a55e896>.overflow-hidden</span> class: </p><div class="container overflow-hidden" data-v-8a55e896><div class="row gx-5" data-v-8a55e896><div class="col" data-v-8a55e896><div class="p-3 mb-1 border bg-light" data-v-8a55e896>Custom column padding</div></div><div class="col" data-v-8a55e896><div class="p-3 mb-1 border bg-light" data-v-8a55e896>Custom column padding</div></div></div></div></div></div></div><div class="col-xl-12" data-v-8a55e896><div class="card custom-card" data-v-8a55e896><div class="card-header" data-v-8a55e896><div class="card-title" data-v-8a55e896> Vertical gutters </div></div><div class="card-body" data-v-8a55e896><p data-v-8a55e896><span class="text-danger" data-v-8a55e896>.gy-*</span> classes can be used to control the vertical gutter widths. Like the horizontal gutters, the vertical gutters can cause some overflow below the .row at the end of a page. If this occurs, you add a wrapper around <span class="text-danger" data-v-8a55e896>.row</span> with the <span class="text-danger" data-v-8a55e896>.overflow-hidden</span> class: </p><div class="container overflow-hidden" data-v-8a55e896><div class="row gy-5" data-v-8a55e896><div class="col-6" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Custom column padding</div></div><div class="col-6" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Custom column padding</div></div><div class="col-6" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Custom column padding</div></div><div class="col-6" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Custom column padding</div></div></div></div></div></div></div></div><div class="row" data-v-8a55e896><div class="col-xl-12" data-v-8a55e896><div class="card custom-card" data-v-8a55e896><div class="card-header" data-v-8a55e896><div class="card-title" data-v-8a55e896> Horizontal &amp; vertical gutters </div></div><div class="card-body" data-v-8a55e896><p data-v-8a55e896><span class="text-danger" data-v-8a55e896>.g-*</span> classes can be used to control the horizontal gutter widths, for the following example we use a smaller gutter width, so there won’t be a need to add the <span class="text-danger" data-v-8a55e896>.overflow-hidden</span> wrapper class.</p><div class="container" data-v-8a55e896><div class="row g-2" data-v-8a55e896><div class="col-6" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Custom column padding</div></div><div class="col-6" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Custom column padding</div></div><div class="col-6" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Custom column padding</div></div><div class="col-6" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Custom column padding</div></div></div></div></div></div></div><div class="col-xl-12" data-v-8a55e896><div class="card custom-card" data-v-8a55e896><div class="card-header" data-v-8a55e896><div class="card-title" data-v-8a55e896> Row columns gutters </div></div><div class="card-body" data-v-8a55e896><p data-v-8a55e896>Gutter classes can also be added to <span class="text-danger" data-v-8a55e896>row columns</span>. In the following example, we use responsive row columns and responsive gutter classes. </p><div class="container" data-v-8a55e896><div class="row row-cols-2 row-cols-lg-5 g-2 g-lg-3" data-v-8a55e896><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div><div class="col" data-v-8a55e896><div class="p-3 border bg-light" data-v-8a55e896>Row column</div></div></div></div></div></div></div><div class="col-xl-12" data-v-8a55e896><div class="card custom-card" data-v-8a55e896><div class="card-header" data-v-8a55e896><div class="card-title" data-v-8a55e896> No gutters </div></div><div class="card-body" data-v-8a55e896><p data-v-8a55e896>The gutters between columns in our predefined grid classes can be removed with <span class="text-danger" data-v-8a55e896>.g-0</span>. This removes the negative <span class="text-danger" data-v-8a55e896>margins</span> from <span class="text-danger" data-v-8a55e896>.row </span>and the horizontal <span class="text-danger" data-v-8a55e896>padding</span> from all immediate children columns. </p><p data-v-8a55e896>Need an edge-to-edge design? Drop the parent <span class="text-danger" data-v-8a55e896>.container</span> or <span class="text-danger" data-v-8a55e896>.container-fluid</span> and add <span class="text-danger" data-v-8a55e896>.mx-0</span> to the <span class="text-danger" data-v-8a55e896>.row</span> to prevent overflow. </p><p data-v-8a55e896>In practice, here’s how it looks. Note you can continue to use this with all other predefined grid classes (including column widths, responsive tiers, reorders, and more).</p><div class="row g-0" data-v-8a55e896><div class="col-sm-6 col-md-8 bd-example-grid" data-v-8a55e896>.col-sm-6 .col-md-8</div><div class="col-6 col-md-4 bd-example-grid" data-v-8a55e896>.col-6 .col-md-4</div></div></div></div></div></div>',2))],64))}},u=s(o,[["__scopeId","data-v-8a55e896"]]);export{u as default};
